.nav-links a{font-size:.9rem;font-weight:500;opacity:.7;transition:opacity .3s ease;white-space:nowrap}
.nav-links a:hover{opacity:1}
.nav-cta{padding:10px 20px !important;border:1px solid rgba(255,255,255,.3) !important;opacity:1 !important;transition:border-color .3s ease !important}
.nav-cta:hover{border-color:#fff !important}
.nav-contact{opacity:1 !important;color:#3B82F6 !important}

.nav-right{display:flex;align-items:center;gap:20px}

