/* ─── Reset & Base ─── */
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth;font-size:16px}
body{font-family:'Inter',system-ui,-apple-system,sans-serif;background:#0A0A0A;color:#fff;line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased}
