/* ─── Reset & Base ─── */
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth;font-size:16px}
body{font-family:'Inter',system-ui,-apple-system,sans-serif;background:#0A0A0A;color:#fff;line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
button{cursor:pointer;border:none;background:none;font-family:inherit;color:inherit}
img{max-width:100%;display:block}
ul{list-style:none}

.container{max-width:1280px;margin:0 auto;padding:0 clamp(20px,4vw,60px)}

/* ─── Typography ─── */
h1{font-size:clamp(2.5rem,6vw,4.5rem);font-weight:800;line-height:1.05;letter-spacing:-0.03em}
h2{font-size:clamp(2rem,4vw,3.2rem);font-weight:700;line-height:1.1;letter-spacing:-0.02em}
h3{font-size:clamp(1.1rem,2vw,1.5rem);font-weight:600;line-height:1.3}

.section-header{margin-bottom:clamp(40px,6vw,80px)}
.section-header p{color:#999;font-size:clamp(1rem,1.5vw,1.25rem);max-width:600px;margin-top:16px}

/* ─── Buttons ─── */
.btn-primary{display:inline-flex;align-items:center;gap:10px;padding:16px 32px;background:#fff;color:#0A0A0A;font-weight:600;font-size:1rem;border-radius:0;transition:all .3s ease}
.btn-primary:hover{background:#3B82F6;color:#fff}
.btn-outline{display:inline-flex;align-items:center;gap:10px;padding:16px 32px;border:1px solid rgba(255,255,255,.3);font-weight:600;font-size:1rem;transition:all .3s ease}
.btn-outline:hover{border-color:#fff;background:rgba(255,255,255,.05)}

/* ─── Navigation ─── */
.nav-header{position:fixed;top:0;left:0;right:0;z-index:1000;padding:0 clamp(20px,4vw,60px);transition:background .3s ease,backdrop-filter .3s ease}
.nav-header.scrolled{background:rgba(10,10,10,.9);backdrop-filter:blur(20px)}
.nav-container{display:flex;align-items:center;justify-content:space-between;height:80px;max-width:1280px;margin:0 auto}
.nav-logo{font-size:1.3rem;font-weight:800;letter-spacing:-.02em;white-space:nowrap}
.nav-links{display:flex;gap:clamp(16px,2.5vw,36px);align-items:center}
.nav-links a{font-size:.9rem;font-weight:500;opacity:.7;transition:opacity .3s ease;white-space:nowrap}
.nav-links a:hover{opacity:1}
.nav-cta{padding:10px 20px !important;border:1px solid rgba(255,255,255,.3) !important;opacity:1 !important;transition:border-color .3s ease !important}
.nav-cta:hover{border-color:#fff !important}
.nav-contact{opacity:1 !important;color:#3B82F6 !important}

.nav-right{display:flex;align-items:center;gap:20px}

/* Language Selector */
.lang-selector{position:relative}
.lang-toggle{display:flex;align-items:center;gap:8px;font-size:.85rem;opacity:.7;transition:opacity .3s}
.lang-toggle:hover{opacity:1}
.lang-dropdown{position:absolute;top:calc(100% + 12px);right:0;background:#1A1A1A;border:1px solid rgba(255,255,255,.1);min-width:160px;opacity:0;visibility:hidden;transform:translateY(-8px);transition:all .25s ease}
.lang-selector.open .lang-dropdown{opacity:1;visibility:visible;transform:translateY(0)}
.lang-dropdown li a{display:block;padding:12px 20px;font-size:.85rem;opacity:.7;transition:all .2s}
.lang-dropdown li a:hover,.lang-dropdown li a.active{opacity:1;background:rgba(255,255,255,.05)}

/* Hamburger */
.nav-hamburger{display:none;flex-direction:column;gap:5px;width:28px;padding:4px 0}
.nav-hamburger span{display:block;height:2px;background:#fff;transition:all .3s ease;border-radius:1px}
.nav-hamburger.active span:nth-child(1){transform:rotate(45deg) translate(5px,5px)}
.nav-hamburger.active span:nth-child(2){opacity:0}
.nav-hamburger.active span:nth-child(3){transform:rotate(-45deg) translate(5px,-5px)}

/* ─── Hero Carousel ─── */
.hero{position:relative;height:100vh;min-height:600px;max-height:1000px;overflow:hidden}
.hero-carousel{height:100%;position:relative}
.hero-slides{height:100%;position:relative}
.hero-slide{position:absolute;inset:0;opacity:0;transition:opacity .8s ease;pointer-events:none;display:flex;align-items:flex-end}
.hero-slide.active{opacity:1;pointer-events:auto}
.hero-slide-bg{position:absolute;inset:0;background-size:cover;background-position:center;transform:scale(1.05);transition:transform 6s ease}
.hero-slide.active .hero-slide-bg{transform:scale(1)}
.hero-overlay{position:absolute;inset:0;background:linear-gradient(to top,rgba(10,10,10,.95) 0%,rgba(10,10,10,.4) 50%,rgba(10,10,10,.2) 100%)}
.hero-content{position:relative;z-index:2;padding:0 clamp(20px,4vw,60px) clamp(80px,12vh,140px);max-width:1280px;margin:0 auto;width:100%}
.hero-tag{display:inline-block;font-size:.8rem;font-weight:600;text-transform:uppercase;letter-spacing:.1em;color:#3B82F6;margin-bottom:20px}
.hero-content h1{margin-bottom:20px}
.hero-content p{font-size:clamp(1rem,1.5vw,1.2rem);color:rgba(255,255,255,.75);max-width:600px;margin-bottom:32px;line-height:1.6}
.hero-cta{display:inline-flex;align-items:center;gap:10px;font-weight:600;font-size:1rem;padding:16px 0;border-bottom:2px solid #fff;transition:border-color .3s}
.hero-cta:hover{border-color:#3B82F6;color:#3B82F6}

.hero-controls{position:absolute;bottom:clamp(30px,5vh,60px);left:0;right:0;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(20px,4vw,60px);max-width:1280px;margin:0 auto;z-index:5}
.hero-dots{display:flex;gap:10px}
.hero-dot{width:40px;height:3px;background:rgba(255,255,255,.3);transition:all .3s ease;border-radius:2px}
.hero-dot.active{background:#fff;width:60px}
.hero-arrows{display:flex;gap:8px}
.hero-arrow{width:48px;height:48px;border:1px solid rgba(255,255,255,.3);display:flex;align-items:center;justify-content:center;transition:all .3s ease}
.hero-arrow:hover{border-color:#fff;background:rgba(255,255,255,.1)}

.hero-progress{position:absolute;bottom:0;left:0;right:0;height:3px;background:rgba(255,255,255,.1);z-index:5}
.hero-progress-bar{height:100%;background:#3B82F6;width:0;transition:width .1s linear}

/* ─── Team Section ─── */
.team-section{padding:clamp(80px,12vw,160px) 0}

.region-tabs{display:flex;gap:0;margin-bottom:clamp(30px,5vw,60px);border-bottom:1px solid rgba(255,255,255,.1)}
.region-tab{padding:16px 28px;font-size:.95rem;font-weight:500;opacity:.5;transition:all .3s ease;position:relative}
.region-tab:hover{opacity:.8}
.region-tab.active{opacity:1}
.region-tab.active::after{content:'';position:absolute;bottom:-1px;left:0;right:0;height:2px;background:#fff}

.team-carousel-wrapper{position:relative}
.team-carousel{display:flex;gap:clamp(20px,3vw,40px);overflow-x:auto;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;scrollbar-width:none;padding-bottom:20px}
.team-carousel::-webkit-scrollbar{display:none}

.team-card{flex:0 0 clamp(300px,40vw,500px);scroll-snap-align:start;background:#111;overflow:hidden;transition:transform .3s ease}
.team-card:hover{transform:translateY(-4px)}
.team-photo{height:320px;background-size:cover;background-position:center top;filter:grayscale(.3);transition:filter .4s ease}
.team-card:hover .team-photo{filter:grayscale(0)}
.team-info{padding:clamp(24px,3vw,36px)}
.team-info blockquote{font-size:.95rem;font-style:italic;color:rgba(255,255,255,.7);line-height:1.7;margin-bottom:24px;position:relative}
.team-info h3{font-size:1.15rem;margin-bottom:4px}
.team-title{font-size:.85rem;color:rgba(255,255,255,.5)}
.team-office{font-size:.85rem;color:#3B82F6;margin-top:4px;margin-bottom:16px}
.team-contact{font-size:.85rem;font-weight:600;display:inline-flex;align-items:center;gap:6px;opacity:.7;transition:opacity .3s}
.team-contact:hover{opacity:1}

.team-nav{display:flex;gap:8px;margin-top:24px}
.team-arrow{width:48px;height:48px;border:1px solid rgba(255,255,255,.2);display:flex;align-items:center;justify-content:center;transition:all .3s}
.team-arrow:hover{border-color:#fff;background:rgba(255,255,255,.05)}

/* ─── Work Showcase ─── */
.work-section{padding:clamp(80px,12vw,160px) 0}
.work-section .container{margin-bottom:clamp(30px,5vw,60px)}

.work-carousel-wrapper{position:relative;padding:0 clamp(20px,4vw,60px)}
.work-carousel{display:flex;gap:clamp(16px,2vw,28px);overflow-x:auto;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;scrollbar-width:none;padding-bottom:20px}
.work-carousel::-webkit-scrollbar{display:none}

.work-card{flex:0 0 clamp(280px,30vw,420px);scroll-snap-align:start;overflow:hidden;transition:transform .3s}
.work-card:hover{transform:translateY(-4px)}
.work-image{height:clamp(200px,25vw,300px);background-size:cover;background-position:center;filter:brightness(.85);transition:filter .4s}
.work-card:hover .work-image{filter:brightness(1)}
.work-details{padding:clamp(16px,2vw,28px) 0}
.work-client{font-size:.8rem;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:#3B82F6;display:block;margin-bottom:8px}
.work-details h3{font-size:clamp(1rem,1.6vw,1.3rem);margin-bottom:12px}
.work-details blockquote{font-size:.85rem;color:rgba(255,255,255,.6);font-style:italic;line-height:1.7;margin-top:12px}
.work-details cite{display:block;font-size:.8rem;margin-top:8px;font-style:normal;color:rgba(255,255,255,.4)}

.work-nav{display:flex;gap:8px;padding:24px clamp(20px,4vw,60px) 0}
.work-arrow{width:48px;height:48px;border:1px solid rgba(255,255,255,.2);display:flex;align-items:center;justify-content:center;transition:all .3s}
.work-arrow:hover{border-color:#fff;background:rgba(255,255,255,.05)}

/* ─── CTA Banner ─── */
.cta-banner{padding:clamp(80px,12vw,160px) 0;background:#111;text-align:center}
.cta-banner h2{margin-bottom:20px}
.cta-banner p{color:rgba(255,255,255,.6);max-width:640px;margin:0 auto 40px;font-size:clamp(1rem,1.5vw,1.15rem);line-height:1.7}

/* ─── How We Work ─── */
.how-section{padding:clamp(80px,12vw,160px) 0}
.how-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(40px,6vw,80px);align-items:center}
.how-image{width:100%;aspect-ratio:4/3;background-size:cover;background-position:center;filter:brightness(.8)}
.how-content h2{margin-bottom:24px}
.how-content p{color:rgba(255,255,255,.6);font-size:clamp(1rem,1.3vw,1.1rem);line-height:1.8;margin-bottom:40px}

/* ─── Insights ─── */
.insights-section{padding:clamp(80px,12vw,160px) 0;background:#0E0E0E}
.insights-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(16px,2vw,28px)}
.insight-card{display:block;overflow:hidden;transition:transform .3s}
.insight-card:hover{transform:translateY(-4px)}
.insight-image{aspect-ratio:4/3;background-size:cover;background-position:center;filter:brightness(.7);transition:filter .4s}
.insight-card:hover .insight-image{filter:brightness(.9)}
.insight-info{padding:clamp(14px,2vw,24px) 0}
.insight-type{font-size:.75rem;font-weight:600;text-transform:uppercase;letter-spacing:.1em;color:#3B82F6;display:block;margin-bottom:8px}
.insight-info h3{font-size:clamp(.9rem,1.2vw,1.1rem);margin-bottom:12px;line-height:1.4}
.insight-cta{font-size:.85rem;font-weight:600;opacity:.5;transition:opacity .3s}
.insight-card:hover .insight-cta{opacity:1}

/* ─── Principles ─── */
.principles-section{padding:clamp(80px,12vw,160px) 0}
.principles-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(20px,3vw,48px)}
.principle-card{padding:clamp(24px,3vw,40px) 0;border-top:1px solid rgba(255,255,255,.15)}
.principle-number{font-size:.85rem;font-weight:700;color:#3B82F6;display:block;margin-bottom:20px}
.principle-card h3{margin-bottom:16px;font-size:clamp(1rem,1.4vw,1.3rem)}
.principle-card p{font-size:.9rem;color:rgba(255,255,255,.5);line-height:1.7}

/* ─── Footer ─── */
.site-footer{padding:clamp(60px,8vw,120px) 0 40px;background:#050505;border-top:1px solid rgba(255,255,255,.06)}
.footer-top{display:grid;grid-template-columns:1fr 1fr;gap:clamp(40px,6vw,80px);margin-bottom:clamp(60px,8vw,100px)}
.footer-cta-block h3{font-size:clamp(1.3rem,2vw,1.8rem);margin-bottom:12px}
.footer-cta-block p{color:rgba(255,255,255,.5);font-size:.95rem;margin-bottom:24px;max-width:400px;line-height:1.6}
.footer-links{margin-bottom:clamp(40px,6vw,60px)}
.footer-col{display:flex;gap:clamp(20px,3vw,40px)}
.footer-col a{font-size:.9rem;opacity:.5;transition:opacity .3s}
.footer-col a:hover{opacity:1}
.footer-bottom{display:flex;align-items:center;justify-content:space-between;padding-top:30px;border-top:1px solid rgba(255,255,255,.06)}
.footer-bottom p{font-size:.8rem;color:rgba(255,255,255,.3)}
.footer-legal{display:flex;gap:24px}
.footer-legal a{font-size:.8rem;color:rgba(255,255,255,.3);transition:color .3s}
.footer-legal a:hover{color:rgba(255,255,255,.7)}

/* ─── Cookie Banner ─── */
.cookie-banner{position:fixed;bottom:0;left:0;right:0;z-index:9999;background:#1A1A1A;border-top:1px solid rgba(255,255,255,.1);padding:20px clamp(20px,4vw,60px);transform:translateY(0);transition:transform .4s ease}
.cookie-banner.hidden{transform:translateY(100%);pointer-events:none}
.cookie-inner{max-width:1280px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:24px}
.cookie-inner p{font-size:.85rem;color:rgba(255,255,255,.6);max-width:600px}
.cookie-actions{display:flex;gap:12px;flex-shrink:0}
.btn-cookie{padding:10px 20px;font-size:.85rem;font-weight:500;transition:all .3s}
.btn-cookie-accept{background:#fff;color:#0A0A0A}
.btn-cookie-accept:hover{background:#3B82F6;color:#fff}
.btn-cookie-decline{border:1px solid rgba(255,255,255,.2)}
.btn-cookie-decline:hover{border-color:#fff}
.btn-cookie-manage{opacity:.6}
.btn-cookie-manage:hover{opacity:1}

/* ─── Responsive ─── */
@media(max-width:1024px){
  .insights-grid{grid-template-columns:repeat(2,1fr)}
  .principles-grid{grid-template-columns:repeat(2,1fr)}
  .how-grid{grid-template-columns:1fr}
  .footer-top{grid-template-columns:1fr}
