@media(max-width:768px){
  .nav-links{position:fixed;top:0;right:-100%;width:80vw;max-width:360px;height:100vh;background:#111;flex-direction:column;padding:100px 40px 40px;gap:24px;transition:right .4s ease;z-index:998}
  .nav-links.open{right:0}
  .nav-hamburger{display:flex;z-index:999}

  .hero{min-height:500px}
  .hero-content{padding-bottom:100px}
  .hero-controls{flex-direction:column-reverse;gap:20px;align-items:flex-start}

  .team-card{flex:0 0 85vw}
  .work-card{flex:0 0 85vw}

  .insights-grid{grid-template-columns:1fr}
  .principles-grid{grid-template-columns:1fr}

  .region-tabs{overflow-x:auto;flex-wrap:nowrap;scrollbar-width:none}
  .region-tabs::-webkit-scrollbar{display:none}
  .region-tab{white-space:nowrap;padding:12px 20px;font-size:.85rem}

  .footer-bottom{flex-direction:column;gap:16px;text-align:center}
  .footer-legal{flex-wrap:wrap;justify-content:center;gap:16px}

  .cookie-inner{flex-direction:column;text-align:center}
  .cookie-actions{flex-wrap:wrap;justify-content:center}
}

